  const api={getItem(k){k=String(k);if(map.has(k))return map.get(k);const cached=store()?.get(k);if(cached!==undefined)return cached;try{return backing?.getItem(k)??null}catch{return null}},setItem(k,v){k=String(k);v=String(v);map.set(k,v);if(owned(k))store()?.write(k,v);else try{backing?.setItem(k,v)}catch{}},removeItem(k){k=String(k);map.delete(k);if(owned(k))store()?.remove(k);try{backing?.removeItem(k)}catch{}},clear(){for(const k of [...map.keys()])if(owned(k))api.removeItem(k)},entries(){return [...map]},key(i){return [...map.keys()][i]??null},get length(){return map.size}};window.ML_SAFE_STORAGE=api;
