 function modelDraftBackup(){const drafts=new Map(window.ML_MODEL_DRAFTS?.entries()||[]);try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith('math-landing:')&&key.includes('assessment-')&&!drafts.has(key)){const value=localStorage.getItem(key);if(value!==null)drafts.set(key,value)}}}catch{}return [...drafts]}
 function openBackup(){modal('Save, restore and manage attempts',teacherTabs()+'<section class="backup-panel"><p>A full backup includes all assessment part plans, locked responses, teacher records, audit history and every saved PNG. Keep it with your assessment files.</p><button id="backupAll">↓ Download full backup</button><label>Restore a full backup <input id="restoreBackup" type="file" accept=".json,application/json"></label><p>To start a fresh attempt for a student, enter their name or rover ID and choose a section. Previous attempts stay in the assessment list.</p><div class="toolbar"><input id="newAttemptName" placeholder="Student name or rover ID" maxlength="50"><select id="newAttemptSection" aria-label="New attempt section">'+sectionOptions(auditSection)+'</select><button id="newAttempt">New attempt</button></div><p id="backupMessage" role="status" class="teacher-message"></p></section>','<button id="backupEnd">End teacher access</button>');wireTabs();$('backupEnd').onclick=endTeacher;$('backupAll').onclick=async()=>{try{const images={};for(const s of state.sessions)for(const r of s.responses){const image=await evidenceGet(r.evidenceKey);if(!image)throw Error('Missing PNG for '+r.pageCode+'. Backup was not created.');images[r.evidenceKey]=image}download('Math-Landing-Assessment-Full-Backup-'+localDate()+'.json',new Blob([JSON.stringify({project:'Math Landing Assessment',version:1,state,images,modelDrafts:modelDraftBackup(),auditNotes:JSON.parse(localStorage.getItem('math-landing:assessment:teacher-audit')||'{}'),auditImages:await ML_TEACHER_ADMIN.backup()})],{type:'application/json'}));$('backupMessage').textContent='Full backup downloaded.'}catch(e){$('backupMessage').textContent=e.message}};
  $('restoreBackup').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const b=JSON.parse(await f.text());if(b.project!=='Math Landing Assessment'||b.version!==1||!Array.isArray(b.state?.sessions)||!b.images)throw Error('Choose a full Math Landing assessment backup.');core.validatePlan(b.state.plan,C);for(const s of b.state.sessions)for(const r of s.responses){if(!r.evidenceKey||!b.images[r.evidenceKey]?.startsWith('data:image/png;base64,'))throw Error('The backup is missing PNG evidence.')}for(const [key,png]of Object.entries(b.images))await evidencePut(key,png);if(b.modelDrafts){if(!Array.isArray(b.modelDrafts)||b.modelDrafts.some(x=>!Array.isArray(x)||x.length!==2||typeof x[0]!=='string'||typeof x[1]!=='string'))throw Error('Invalid model drafts in backup.');for(const [key,value]of b.modelDrafts)window.ML_MODEL_DRAFTS.write(key,value);await window.ML_MODEL_DRAFTS.flush()}if(b.auditNotes){const notes={...JSON.parse(localStorage.getItem('math-landing:assessment:teacher-audit')||'{}'),...b.auditNotes};localStorage.setItem('math-landing:assessment:teacher-audit',JSON.stringify(notes));await ML_TEACHER_ADMIN.restore(b.auditImages||[])}const before=state;state={...b.state,pageNotes:{...b.state.pageNotes,...state.pageNotes},sessions:[...state.sessions.filter(x=>!b.state.sessions.some(y=>y.id===x.id)),...b.state.sessions]};syncSubtraction();syncBalance();syncListed();syncCurrentPages();syncRequestedPages();syncTapControls();syncThreeParts();ML_ASSESSMENT_REFINEMENTS.migrate(state);try{await persist()}catch(e){state=before;throw e}active=null;show('entry');entryCards();$('backupMessage').textContent='Backup restored. Existing attempts with other IDs were kept.'}catch(e){$('backupMessage').textContent='Restore failed: '+e.message}};
  $('newAttempt').onclick=async()=>{const name=$('newAttemptName').value.trim(),s=state.plan.sections.find(x=>x.key===$('newAttemptSection').value);if(!name){$('backupMessage').textContent='Enter the student name or rover ID.';return}state.sessions.push({id:crypto.randomUUID(),student:name,sectionKey:s.key,planRevision:s.part===4?state.plan.fourPartRevision:state.plan.contentRevision,grade:s.grade,part:s.part,pages:s.pages.map(code=>clone(C.find(q=>q.pageCode===code))),responses:[],startedAt:now(),provisional:!!state.plan.provisional});try{await persist();$('backupMessage').textContent='New attempt ready. Close teacher access and use that student ID.'}catch(e){state.sessions.pop();$('backupMessage').textContent='Could not save a new attempt.'}};
 }

 function liveAuditContext(){if(current&&active)return{id:'assessment-audit:'+active.sectionKey+':'+current.pageCode,pageId:current.id,pageCode:current.pageCode,title:current.title,type:'question',where:sectionName(active),sectionKey:active.sectionKey,grade:active.grade,codes:current.codes,contextLabel:current.prompt||current.config.review?.prompt||'',view:'assessment'};const done=!$('complete').hidden;return{id:done?'assessment-audit:complete:'+active.sectionKey:'assessment-audit:entry',pageId:done?'assessment-complete':'assessment-entry',pageCode:done?'COMPLETE-'+active.sectionKey.toUpperCase():'ENTRY',title:done?'Complete · '+sectionName(active):'Student entry screen',type:'screen',where:done?sectionName(active):'Four assessment sections',sectionKey:active?.sectionKey,grade:active?.grade,codes:[],view:done?'complete':'entry'};}
 function auditContext(){if(auditLive)return liveAuditContext();const s=state.plan.sections.find(x=>x.key===auditSection)||state.plan.sections[0],q=C.find(p=>p.pageCode===s.pages[auditIndex]);return{id:'assessment-audit:'+s.key+':'+q.pageCode,pageId:q.id,pageCode:q.pageCode,title:q.title,type:'question',where:sectionName(s),sectionKey:s.key,planRevision:s.part===4?state.plan.fourPartRevision:state.plan.contentRevision,grade:s.grade,codes:q.codes,contextLabel:q.prompt||q.config.review?.prompt||''};}
 function updateTeacherTick(){refreshPageNote();const b=$('pageEditTick');if(!b)return;b.hidden=!auditUnlocked;b.disabled=loading||locking||starting||switchingStudent;b.setAttribute('aria-pressed',String(auditUnlocked&&!!window.ML_TEACHER_ADMIN?.flags().some(n=>n.id===liveAuditContext().id)));}
