 async function captureAuditCanvas(){const ctx=auditContext();if(auditLive&&ctx.type==='screen')return html2canvas(document.body,{width:innerWidth,height:innerHeight,windowWidth:innerWidth,windowHeight:innerHeight,scale:1,logging:false,backgroundColor:'#fff8ea',ignoreElements:e=>e.matches?.('dialog,#teacherAuditDock,#toast,#pageEditTick')});const s=state.plan.sections.find(p=>p.key===ctx.sectionKey),q=auditLive?current:C.find(p=>p.pageCode===ctx.pageCode),png=await capture(auditLive?$('engine'):$('auditFrame'),q,auditLive?active:{...s,student:'Teacher audit'}),img=new Image();img.src=png;await img.decode();const c=document.createElement('canvas');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);return c;}
 function auditReviewModal(title,body,footer){const d=$('auditReviewDialog');ML_TEACHER_ADMIN.resetEditor();$('auditReviewTitle').textContent=title;$('auditReviewBody').innerHTML=body;$('auditReviewFooter').innerHTML=footer;if(!d.open)d.showModal();$('auditReviewClose').focus();}
 ML_TEACHER_ADMIN.init({context:auditContext,stop:stopVoice,toast,modal:auditReviewModal,navigate:note=>{if(note.type==='screen'){auditLive=true;$('dialog').close();if(note.view==='complete'){const saved=state.sessions.filter(s=>s.sectionKey===note.sectionKey&&s.completedAt).at(-1);if(saved){active=saved;showComplete()}}else{active=null;current=null;show('entry');entryCards()}return}auditSection=note.sectionKey||auditSection;let s=state.plan.sections.find(x=>x.key===auditSection);if(!s?.pages.includes(note.pageCode))s=state.plan.sections.find(x=>x.pages.includes(note.pageCode));if(s){auditSection=s.key;const i=s.pages.indexOf(note.pageCode);if(i>=0)auditIndex=i}openAudit()},capture:captureAuditCanvas,download:(name,type,data)=>download(name,data instanceof Blob?data:new Blob([data],{type}))});
 addEventListener('resize',fitAuditPreview);$('auditReviewClose').onclick=()=>$('auditReviewDialog').close();
